const translationKeys = Object.keys(arabicTranslations).sort((a, b) => b.length - a.length);
const englishTranslations = Object.fromEntries(translationKeys.map(key => [arabicTranslations[key], key]));
const arabicKeys = Object.keys(englishTranslations).sort((a, b) => b.length - a.length);
const originalTextNodes = new WeakMap<Text, string>();
const originalAttributes = new WeakMap<Element, Record<string, string>>();
function localizeDocument(lang: Lang) {
  if (typeof document === 'undefined') return;
  const root = document.body;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  let node: Node | null;
  while ((node = walker.nextNode())) nodes.push(node as Text);
  for (const textNode of nodes) {
    if (textNode.parentElement?.closest('script,style')) continue;
    const source = originalTextNodes.get(textNode) ?? textNode.nodeValue ?? '';
    if (!originalTextNodes.has(textNode)) originalTextNodes.set(textNode, source);
    let value = source;
    if (lang === 'ar') for (const key of translationKeys) value = value.split(key).join(arabicTranslations[key]);
    else for (const key of arabicKeys) value = value.split(key).join(englishTranslations[key]);
    if (textNode.nodeValue !== value) textNode.nodeValue = value;
  }
  const elements = root.querySelectorAll<HTMLElement>('input,textarea,button,select,[aria-label],[title]');
  elements.forEach(element => {
    const attrs = originalAttributes.get(element) ?? {};
    for (const attribute of ['placeholder', 'aria-label', 'title']) {
      const source = attrs[attribute] ?? element.getAttribute(attribute);
      if (!source) continue;
      attrs[attribute] = source;
      let value = source;
      if (lang === 'ar') for (const key of translationKeys) value = value.split(key).join(arabicTranslations[key]);
      else for (const key of arabicKeys) value = value.split(key).join(englishTranslations[key]);
      element.setAttribute(attribute, value);
    }
    originalAttributes.set(element, attrs);
  });
}
function read<T>(key: string, fallback: T): T { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; } }
function write(key: string, value: unknown) { localStorage.setItem(key, JSON.stringify(value)); }
function normalizeEmail(email: string) { return email.trim().toLowerCase(); }
const personalEmailDomains = new Set(['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'hotmail.com', 'outlook.com', 'live.com', 'icloud.com', 'me.com', 'mac.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.net', 'mail.com', 'yandex.com', 'yandex.ru', 'zoho.com']);
function businessEmailError(email: string) {
  const normalized = normalizeEmail(email);
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(normalized)) return 'Enter a valid business email address.';
  const domain = normalized.split('@')[1] ?? '';
  const regionalPersonalDomain = /^(yahoo|hotmail|outlook|live)\.[a-z]{2,3}(\.[a-z]{2})?$/.test(domain);
  if (personalEmailDomains.has(domain) || regionalPersonalDomain) return 'Please use a business-domain email. Personal email providers are not accepted.';
  return '';
}
function isCandidateComplete(candidate: Candidate) {
  return Boolean(candidate.name.trim() && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(candidate.email.trim()) && candidate.phone.trim() && candidate.city.trim() && candidate.experience && candidate.sector && candidate.salary && candidate.availability && candidate.certifications.length && candidate.cvFilename.trim() && (!candidate.certifications.includes('Other') || candidate.otherCertification.trim()));
}
function candidateCompletionPercent(candidate: Candidate) {
  const hasOther = candidate.certifications.includes('Other');
  const checks: (string | boolean)[] = [candidate.name.trim(), /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(candidate.email.trim()), candidate.phone.trim(), candidate.city.trim(), candidate.experience, candidate.certifications.length > 0, candidate.sector, candidate.salary, candidate.availability, candidate.cvFilename.trim()];
  if (hasOther) checks.push(candidate.otherCertification.trim());
  return Math.round((checks.filter(Boolean).length / checks.length) * 100);
}
function withCandidateCompleteness(candidate: Candidate): Candidate {
  return { ...candidate, complete: isCandidateComplete(candidate) };
}
function readCandidates(): Record<string, Candidate> {
  const saved = read<Record<string, Candidate> | null>(STORAGE.candidates, null);
  if (saved) return Object.fromEntries(Object.entries(saved).map(([email, candidate]) => [normalizeEmail(email), withCandidateCompleteness({ ...candidate, id: candidate.id || 'candidate-2048', cvFilename: candidate.cvFilename || '' })]));
  const legacy = read<Candidate | null>(STORAGE.candidate, null);
  return legacy?.email ? { [normalizeEmail(legacy.email)]: withCandidateCompleteness({ ...legacy, id: legacy.id || 'candidate-2048', cvFilename: legacy.cvFilename || '' }) } : {};
}
function saveCandidate(candidate: Candidate, previousEmail?: string) {
  const candidates = readCandidates();
  if (previousEmail && normalizeEmail(previousEmail) !== normalizeEmail(candidate.email)) delete candidates[normalizeEmail(previousEmail)];
  candidates[normalizeEmail(candidate.email)] = withCandidateCompleteness(candidate);
  write(STORAGE.candidates, candidates);
}
function findCandidate(email: string) {
  return readCandidates()[normalizeEmail(email)] ?? null;
}
function readCompanies(): Record<string, Company> {
  const saved = read<Record<string, Company> | null>(STORAGE.companies, null);
  if (saved) return Object.fromEntries(Object.entries(saved).map(([email, company]) => [normalizeEmail(email), company]));
  const legacy = read<Company | null>(STORAGE.company, null);
  return legacy?.email ? { [normalizeEmail(legacy.email)]: legacy } : {};
}
function saveCompany(company: Company, previousEmail?: string) {
  const companies = readCompanies();
  if (previousEmail && normalizeEmail(previousEmail) !== normalizeEmail(company.email)) delete companies[normalizeEmail(previousEmail)];
  companies[normalizeEmail(company.email)] = company;
  write(STORAGE.companies, companies);
}
function findCompany(email: string) {
  return readCompanies()[normalizeEmail(email)] ?? null;
}
function missingCompanyRequirements(company: Company) {
  const missing: string[] = [];
  if (businessEmailError(company.email)) missing.push('enter a valid business-domain email');
  if (!['Basic', 'Pro', 'Enterprise'].includes(company.plan)) missing.push('select a Basic, Pro or Enterprise plan');
  return missing;
}
function canAccessCompanyDashboard(company: Company) {
  return missingCompanyRequirements(company).length === 0;
}
function dashboardFor(session: Session) {
  return session.role === 'candidate' ? '/candidate/dashboard' : '/company/dashboard';
}
function candidateSearchProfiles() {
  const accounts = Object.values(readCandidates());
  const accountIds = new Set(accounts.map(candidate => candidate.id));
  const savedProfiles = accounts.map(candidate => ({
    id: candidate.id,
    experience: candidate.experience,
    city: candidate.city,
    certifications: candidate.certifications.map(cert => cert === 'Other' ? `Other: ${candidate.otherCertification}` : cert),
    sector: candidate.sector,
    availability: candidate.availability,
    complete: isCandidateComplete(candidate),
  }));
  return [...candidateDirectory.filter(candidate => !accountIds.has(candidate.id)), ...savedProfiles].filter(candidate => candidate.complete);
}
const demoMatchIdentities: Record<string, { name: string; email: string; phone: string; sector: string }> = {
  'candidate-2048': { name: demoCandidate.name, email: demoCandidate.email, phone: demoCandidate.phone, sector: demoCandidate.sector },
  'candidate-1731': { name: 'Maha Al-Mutairi', email: 'maha.demo@example.com', phone: '+966 55 000 1731', sector: 'Manufacturing' },
  'candidate-3906': { name: 'Faisal Al-Qahtani', email: 'faisal.demo@example.com', phone: '+966 55 000 3906', sector: 'Energy' },
  'candidate-4420': { name: 'Noura Al-Shehri', email: 'noura.demo@example.com', phone: '+966 55 000 4420', sector: 'Infrastructure' },
};
function candidateMatchIdentity(id: string) {
  const registered = Object.values(readCandidates()).find(candidate => candidate.id === id);
  return registered ? { name: registered.name, email: registered.email, phone: registered.phone, sector: registered.sector } : demoMatchIdentities[id] ?? null;
}

